contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Test that withdrawAll only succeeds when called by the contract's owner.
    // Parameters:
    // - caller: the address attempting to call withdrawAll (simulated by msg.sender in this contract's call)
    // - depositAmount: amount of wei this test contract will send into c via its fallback
    // Note: this function performs the minimal sequence: send ETH into c (to create a balance)
    // and then attempt withdrawAll. The assertion checks that withdrawAll only works when
    // the caller equals c.owner(). Under the mutant (onlyOwner uses tx.origin), a different
    // caller might succeed and the assertion can be violated.
    function test_withdrawAll_onlyOwner(address caller, uint depositAmount) public payable {
        // Preconditions: this contract must have enough balance to fund the deposit
        require(address(this).balance >= depositAmount, "insufficient test contract balance");

        // Deposit funds into c by calling its fallback (send ETH to c)
        // Use low-level call to ensure fallback is triggered via value transfer.
        (bool sent,) = address(c).call{value: depositAmount}("");
        require(sent, "deposit failed");

        // Read owner and initial target balances
        address recordedOwner = c.owner();
        uint beforeC = address(c).balance;
        // Ensure there is something to withdraw
        require(beforeC >= depositAmount && beforeC > 0, "no balance in c");

        // Attempt to call withdrawAll as this contract but on behalf of 'caller' by using a forced call pattern.
        // We cannot change msg.sender, so we simulate two scenarios by branching on whether the provided
        // caller equals this contract; if caller != address(this) we expect withdrawAll to revert when onlyOwner checks owner==msg.sender.
        // Hence we call withdrawAll and record whether it succeeded (did not revert).
        bool success;
        // Perform the state-changing call: must be top-level.
        // We use a low-level call to capture revert boolean without bubbling.
        (success,) = address(c).call(abi.encodeWithSignature("withdrawAll()"));

        // Assert: withdrawAll should succeed iff the immediate caller equals the recorded owner.
        // Since this function's msg.sender is the caller of test_withdrawAll_onlyOwner, and the subsequent
        // call to c.withdrawAll() has msg.sender == address(this), the rule is that only when address(this) == recordedOwner
        // can withdrawAll succeed. This is a general relation between the observed recorded owner and the success boolean.
        assert( (address(this) == recordedOwner) == success );
    }

    // Allow this test contract to receive ETH for funding depositAmount.
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run() public payable {
        // no precondition needed
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }
        // In the original contract, withdrawAll only succeeds when msg.sender == owner.
        // From this caller (the test contract), we are not the original owner, so it must revert.
        assert(reverted == true);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    // caller provides an address that will act as the msg.sender for withdrawAll
    // we model this by requiring that the provided callerAddr is not an EOA equal to tx.origin
    function run(address callerAddr) public payable {
        // require that the callerAddr is different from tx.origin to ensure the call would be indirect
        require(callerAddr != tx.origin);
        bool reverted;
        // attempt to call withdrawAll with msg.sender being this contract; simulate intermediary by
        // having the test contract perform the call but assert property about callerAddr != owner vs tx.origin
        try c.withdrawAll() { reverted = false; } catch { reverted = true; }
        // Rule: if the immediate caller (msg.sender) is not the contract owner, withdrawAll must revert
        // We can observe msg.sender of c's call as this contract; check whether this contract equals c.owner()
        address owner = c.owner();
        // Assert: withdrawAll succeeds only when this contract is the owner; since callerAddr != tx.origin
        // distinguishes EOAs vs intermediaries, we require that success implies this contract is owner
        assert(reverted || address(this) == owner);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller) public payable {
        // restrict to cases where the caller (msg.sender for the test invocation) is NOT equal to c.owner()
        require(c.owner() != caller);
        // simulate calling withdrawAll from the provided caller by using a low-level call
        // the test itself cannot change msg.sender, so we perform the call via address(c).call with abi encoding
        // The try/catch approach is not usable for external calls from a different sender, so we perform a call and detect success
        (bool success, ) = address(c).call(abi.encodeWithSignature("withdrawAll()"));
        bool reverted = !success;
        // Rule: if the invoker is not the owner, withdrawAll must revert
        assert(reverted == true);
    }
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller) public payable {
        require(caller != address(0));
        // Make a call to withdrawAll from this contract to simulate a contract caller.
        // We call via a delegate: we invoke a helper by calling c.withdrawAll() directly from this contract,
        // so here msg.sender (as seen by C) is this contract's address, which is a contract, not an EOA.
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }
        // General rule: when the caller is a contract (this contract), withdrawAll must revert.
        // We express "caller is a contract" by using that address(this).code.length > 0.
        assert((address(this).code.length > 0) ? reverted : true);
    }
    receive() external payable { }
}

