pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: amount to send and whether the caller uses a forwarding contract
    function testFuzz_property(uint256 amount, bool useForwarder) public {
        // keep amount in a reasonable range so it fits in balance and vm.deal
        amount = bound(amount, 0, 1 ether);

        // fund the contract so sendMoney can forward value
        vm.deal(address(this), 2 ether);
        // make this contract the owner (it is by construction) and deposit some ether into c
        // deposit by calling fallback payable
        c.sendMoney{value: 0}(address(this), 0); // harmless, but ensure contract exists
        // send some Ether into c via a direct call to its fallback
        (bool s,) = address(c).call{value: 1 ether}("");
        require(s);

        // record balance before
        uint256 before = address(c).balance;

        // prepare target: we need an adversarial helper if useForwarder is true
        address target;
        if (useForwarder) {
            Forwarder f = new Forwarder();
            target = address(f);
        } else {
            // a regular EOA (this contract) will behave as a simple target that accepts funds
            target = address(this);
        }

        // owner (this contract) calls sendMoney to forward 'amount' to target
        // ensure this contract has ETH to pay for forwarding (not needed, c sends funds)
        vm.prank(address(this));
        bool ok;
        try c.sendMoney(target, amount) {
            ok = true;
        } catch {
            ok = false;
        }

        // After sendMoney returns (or reverts), reference contract C guarantees that when
        // the caller is the owner, onlyOwner succeeds and the contract's balance is either
        // reduced by the forwarded amount on success, or unchanged on revert. The mutant
        // using tx.origin can allow a non-owner EOA to cause onlyOwner to pass when invoked
        // through an intermediate contract, leading to different outcomes for some inputs.

        // Single assertion that the reference preserves a non-negative balance relation:
        // If the call succeeded, the contract balance must be exactly before - amount;
        // if the call reverted, the balance must be unchanged. This universal fact holds
        // for the correct contract but the mutant can violate it for some inputs when
        // tx.origin-based check erroneously allows owner-only action from a non-owner path.
        if (ok) {
            assertTrue(address(c).balance == before - amount);
        } else {
            assertTrue(address(c).balance == before);
        }
    }
}

// adversarial forwarding contract: accepts ETH and does nothing special
contract Forwarder {
    receive() external payable {}
}

