pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: amount to send and whether the intermediary should be used
    function testFuzz_property(uint256 amount, bool useIntermediary) public {
        // keep amount reasonable relative to uint256 and within caller balances
        amount = bound(amount, 0, 1 ether);

        // Fund the contract so there's something to send/withdraw
        vm.deal(address(this), 2 ether);

        // The owner is the deployer (setUp did new C() from this address), so msg.sender == owner here.
        // Make the contract hold some Ether so sendMoney can send out funds.
        // Send 1 ether into c
        c.sendMoney{value: 0}(address(this), 0); // harmless, ensure contract exists (no-op)
        // Fund the contract by sending directly to its fallback (which increments depositsCount but also accepts ether)
        (bool s,) = address(c).call{value: 1 ether}("");
        require(s);

        // Decide the target: either a benign EOA (this contract's address) or an adversarial intermediary
        address target;
        Attacker attacker;
        if (useIntermediary) {
            attacker = new Attacker(address(c));
            target = address(attacker);
        } else {
            target = address(this); // benign
        }

        // As owner (this), call sendMoney to instruct c to send `amount` to target
        // Ensure this contract has enough balance for the call (needed only for vm.prank if used but we call as this)
        // c.sendMoney is owner-only so currently this call should succeed on the reference implementation
        bool ok;
        try c.sendMoney(target, amount) {
            ok = true;
        } catch {
            ok = false;
        }

        // After sendMoney, on the correct contract the owner should still be able to withdraw the entire remaining balance.
        // We observe this by calling withdrawAll() as owner and ensuring the call succeeds (does not revert)
        bool withdrawOk;
        try c.withdrawAll() {
            withdrawOk = true;
        } catch {
            withdrawOk = false;
        }

        // Single assertion: on the reference contract, withdrawAll always succeeds here for any inputs; the mutant that uses tx.origin can be made to fail for some choices (useIntermediary==true and attacker crafted)
        assertTrue(withdrawOk);
    }
}

// Adversarial intermediary: will call c.sendMoney on behalf of the tx origin to create a scenario where tx.origin-based onlyOwner may behave differently.
contract Attacker {
    C public targetC;
    constructor(address _c) payable {
        targetC = C(_c);
    }
    // Accept ether so c can send to us
    fallback() external payable {}
}

