pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: callerBalance is the EOA balance to fund the attacker intermediate contract; value is amount to send
    function testFuzz_property(uint256 callerBalance, uint256 value) public {
        // keep amounts reasonable and non-zero where useful
        callerBalance = bound(callerBalance, 1 wei, 1 ether);
        value = bound(value, 1 wei, 1 ether);

        // Deploy an intermediate contract that will call c.sendMoney(target, value) when triggered.
        AttackerIntermediate intermediate = new AttackerIntermediate(address(c));

        // Fund owner EOA (which is the test contract deployer and owner of c) so tx.origin can be the owner
        address ownerEOA = address(this); // setUp deployed c, so this is owner
        vm.deal(ownerEOA, callerBalance);

        // Fund the intermediate contract from the owner EOA to simulate a transaction where tx.origin == ownerEOA
        // We perform a prank so the transfer originates from ownerEOA
        vm.prank(ownerEOA);
        (bool sent,) = payable(address(intermediate)).call{value: value}("");
        require(sent, "funding intermediate failed");

        // Now, have the intermediate call c.sendMoney targeting some recipient (we use address(1)).
        // We call intermediate.performSend with no prank: msg.sender will be the intermediate contract.
        bool ok;
        try intermediate.performSend(address(1), value) {
            ok = true;
        } catch {
            ok = false;
        }

        // The invariant: In the reference contract, only the owner (msg.sender == owner) may call sendMoney.
        // Here msg.sender is the intermediate contract (not the owner), so the reference must revert and ok==false for ALL admissible inputs.
        // The mutant (tx.origin==owner) will see tx.origin==ownerEOA and allow the call, making ok==true for some inputs.
        assertTrue(!ok);
    }
}

// Minimal adversarial intermediate that receives funds and then calls c.sendMoney
contract AttackerIntermediate {
    C target;
    constructor(address _t) {
        target = C(_t);
    }
    receive() external payable {}
    function performSend(address _to, uint _value) external {
        // call sendMoney on the target; msg.sender here is this contract
        target.sendMoney(_to, _value);
    }
}

