pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameter: amount to deposit and whether the recipient will revert (encoded as a boolean by using an address selector)
    function testFuzz_property(uint256 depositAmount, bool revertOnReceive) public {
        // keep depositAmount within a reasonable wide bound
        depositAmount = bound(depositAmount, 0, 1 ether);

        // deploy an adversarial helper that either accepts or reverts upon receiving funds
        Receiver helper = new Receiver(revertOnReceive);

        // fund the contract C with the deposit amount from some EOA
        vm.deal(address(this), depositAmount);
        // send deposit via fallback to increment depositsCount and increase contract balance
        (bool ok,) = address(c).call{value: depositAmount}("");
        // the call should succeed (sending to fallback)
        require(ok);

        // owner is this test contract (set in C constructor), so calling withdrawAll as owner
        bool didCallSucceed;
        // attempt withdrawAll where the contract will transfer funds to msg.sender (owner)
        // we simulate a scenario where msg.sender will forward the funds to helper by using helper as target
        // but since withdrawAll sends to msg.sender, we instead make the owner be a contract that will
        // receive the transfer and internally forward to helper. To do that, we deploy an OwnerForwarder
        OwnerForwarder forwarder = new OwnerForwarder(address(helper));

        // make forwarder the owner by creating a fresh instance of C? We cannot change owner in c.
        // Instead, we simulate the behaviour by directly calling c.withdraw to the test's msg.sender
        // but the distinguishing behavior is about transfer path to recipient that reverts: we test by
        // calling c.sendMoney to the helper (onlyOwner) to check how contract behaves when transferring
        // to a reverting recipient; however the mutation specifically changed withdrawAll implementation.
        // To observe a difference via public surface, we try to call withdrawAll via a prank where msg.sender
        // is the forwarder (so c sees msg.sender = forwarder and will transfer to it). The forwarder
        // will on receive attempt to forward to helper which can revert.

        // fund the forwarder so it can be owner when C was deployed by this test contract; but owner is c.owner == this test address,
        // we need c.owner to be forwarder. To achieve that we must deploy a fresh C where owner is forwarder.
        // The test requires using c from setUp(); we instead simulate the difference by interacting with c while
        // pranking as the original owner (this) but forwarding will exercise recipient revert behavior by making
        // the owner be a contract: deploy new C instance where owner is forwarder. The harness mandates using `c = new C()` in setUp(),
        // but we can still deploy additional C instances locally to exercise the property. We'll call withdrawAll on a freshly
        // deployed instance c2 whose owner is the deployer (which will be the test by default). To set owner to forwarder,
        // we must deploy c2 from the forwarder; so have the forwarder deploy C and then call withdrawAll. That requires Factory in forwarder.

        // deploy forwarder that can deploy C from its address
        Deployer deployer = new Deployer();
        // have deployer (a different contract) deploy a C from itself so it's the owner
        C c2 = deployer.deployC();

        // fund c2
        vm.deal(address(this), depositAmount);
        (bool ok2,) = address(c2).call{value: depositAmount}("");
        require(ok2);

        // now call withdrawAll as the deployer (owner) by making the tx originate from deployer
        // but deployer will on receiving the funds forward to helper which may revert; to let deployer forward, we set its forward target
        deployer.setForwardTarget(address(helper));

        // perform the call from deployer context
        try deployer.callWithdrawAll(c2) {
            didCallSucceed = true;
        } catch {
            didCallSucceed = false;
        }

        // General rule assertion: For the reference implementation, when the recipient of the transfer during withdrawAll
        // reverts on receive, the withdrawAll call from the owner will revert (i.e., didCallSucceed == false) for at least some inputs
        // The mutant that uses a direct transfer to msg.sender can differ in whether the call reverts/succeeds; we assert that
        // the reference's observed behavior is a boolean (here we assert that either it succeeds or fails depending on revertOnReceive),
        // but we must provide a universal property: if helper reverts on receive, then withdrawAll MUST revert (i.e., didCallSucceed == false).

        if (revertOnReceive) {
            assertTrue(!didCallSucceed);
        } else {
            assertTrue(didCallSucceed);
        }
    }
}

// Helper contracts
contract Receiver {
    bool public shouldRevert;
    constructor(bool _r) { shouldRevert = _r; }
    receive() external payable {
        if (shouldRevert) revert("recv revert");
    }
}

contract OwnerForwarder {
    address public target;
    constructor(address _t) { target = _t; }
    receive() external payable {
        // forward to target; ignore success to mimic various behaviors
        (bool s,) = target.call{value: msg.value}("");
        if (!s) revert("forward failed");
    }
}

contract Deployer {
    address public forwardTarget;
    function deployC() public returns (C) {
        C c = new C();
        return c;
    }
    function setForwardTarget(address t) public { forwardTarget = t; }
    function callWithdrawAll(C c) public {
        c.withdrawAll();
    }
}

